package erratum

import (
	"errors"
)

// Use opens a resource via opener (retrying on TransientError), calls
// Frob(input) on it, and ensures Close is called exactly once. Panics from
// Frob are recovered: a FrobError triggers Defrob with its defrobTag, and
// the error is returned from Use.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if errors.As(err, &transient) {
			continue
		}
		return err
	}

	// Registered first, so it runs last (LIFO): after any Defrob from the
	// recover block below, Close is still called exactly once.
	defer resource.Close()

	defer func() {
		if r := recover(); r != nil {
			switch e := r.(type) {
			case FrobError:
				resource.Defrob(e.defrobTag)
				err = e
			case error:
				err = e
			default:
				// Not an error at all; let the panic propagate.
				panic(r)
			}
		}
	}()

	resource.Frob(input)
	return nil
}
